// Source-derived mission text from Fort Hendrix rulebook, pp. 19–24.
private val fortMissionDetails = mapOf(
"M1" to FortMissionInfo("Gathering the Braves", "Medium", "60 minutes", listOf("3V","7R","6V","1R","2R","9V"), "Gather all Survivors in the same Zone.", "10am", briefing = "Penny Kirkland was a friend long before the invasion. Her mother, Dr. Linda Kirkland, a government biologist working at Fort Hendrix, sent increasingly worried messages about wet-work experiments on zombies. Her last message was a call for help from the base. As the Survivors approached Fort Hendrix, unknown attackers opened fire and they took shelter in an abandoned shop.", objectives = listOf("Gather all Survivors in the same Zone. As soon as this is done, read Note #1.", "Starting hour: 10am."), specialRules = listOf("Penny accompanies the team as a Companion. Choose her Leader during Setup; Penny does not gain AP or CXP. If Penny dies, the campaign is lost.", "Setup: place Javier, Karl, and Riley on Starting Zone #1 (tile 1R/3V); Marian, Michelle, Penny, and Wayne on Starting Zone #2 (tile 7R). Penny’s Leader must start in Zone #2. Resolve a Zombie Phase before the first Game Round.", "Until the Objective is met, Objective card #7 (A collection of electronic stuff) is the only card Survivors can take.", "While in Penny’s Zone, Survivors (including Penny and her Leader) gain Low Profile: they cannot be hit by Friendly Fire; ignore them when shooting into their Zone. Molotovs still apply.", "Each Pimpweapon Crate gives a random Pimpweapon; the Survivor may reorganize inventory for free."), materials = listOf("6 Survivor Starting Zone markers", "Spawn Zone tokens", "6 Pimpweapon Crates", "6 Objective cards", "2 Notes")),
"M2" to FortMissionInfo("Digital Clues", "Medium", "60 minutes", listOf("17R","2R","18R","20R","19R","1R"), "Go to the Command Office on tile 19R.", "7am", briefing = "The Survivors welcomed soldiers who were also heading to Fort Hendrix. They planned to locate Dr. Kirkland’s last known position through the base servers, but first needed the key to the building housing them. Their best lead was the base’s leading officer.", objectives = listOf("Check the office: go to the Command Office and take its Objective card on tile 19R.", "Starting hour: 7am."), specialRules = listOf("The building on tile 20R cannot be opened.", "First visit the Guardhouse and Command Office; only those two Objective cards can be taken.", "While in Penny’s Zone, Survivors gain Low Profile: they cannot be hit by Friendly Fire; ignore them when shooting into their Zone. Molotovs still apply.", "Each Pimpweapon Crate gives a random Pimpweapon; the Survivor may reorganize inventory for free."), materials = listOf("6 Survivor Starting Zone markers", "Spawn Zone tokens", "6 Pimpweapon Crates", "6 Objective cards", "1 Note")),
"M3" to FortMissionInfo("Send My Love to Linda", "Medium", "90 minutes", listOf("17R","21R","9R","18V","4V","19V"), "Take Objective cards until you find a lead to Penny's mother.", "9am", briefing = "Searching Fort Hendrix’s servers quickly located the sector where Linda Kirkland sent her last email. The Survivors rushed there, hoping to find her and learn more about the zombie invasion, despite fearing there was little chance she was alive.", objectives = listOf("Rescue Dr. Linda Kirkland. Take Objective cards until you find a lead to Penny’s mother.", "Starting hour: 9am."), specialRules = listOf("While in Penny’s Zone, Survivors gain Low Profile: they cannot be hit by Friendly Fire; ignore them when shooting into their Zone. Molotovs still apply.", "The building straddling tiles 17R and 21R cannot be opened.", "Each Pimpweapon Crate gives a random Pimpweapon; the Survivor may reorganize inventory for free."), materials = listOf("Survivor Starting Zone marker", "Spawn Zone tokens", "6 Pimpweapon Crates", "6 Objective cards", "1 Note")),
"M4" to FortMissionInfo("Secret Lab", "Medium", "60 minutes", listOf("17R","16R","19V","20V"), "Take Objective cards until you find a way to prevent the zombies from spreading various plagues.", "4am", briefing = "For the first time, the Survivors saw fear in each other. They were searching for a secret laboratory that might be haunted by zombies and infected with lethal diseases. They had to destroy it before other survivors faced the same nightmare.", objectives = listOf("Secure the secret lab. Take Objective cards until you find a way to make sure the Zombies won’t spread various plagues.", "Starting hour: 4am."), specialRules = listOf("Red doors cannot be opened from street Zones; they can only be opened from inside the building.", "The Pimpmobile cannot be Driven or Searched until stated otherwise.", "Penny’s Leader gets the +1 free Combat Action Skill. This free Combat Action can only be performed with a weapon in the Leader’s Backpack.", "Each Pimpweapon Crate gives a random Pimpweapon; the Survivor may reorganize inventory for free."), materials = listOf("Survivor Starting Zone marker", "8 Objective cards", "3 Spawn Zone tokens", "4 Pimpweapon Crates", "Closed door tokens", "Pimpmobile")),
"M5" to FortMissionInfo("Pathogen Eden", "Medium", "45 minutes", listOf("7R","6R","19V","16R","4R","17V"), "Destroy the laboratories and any Zombies standing in them; take the Refrigerators Objective card on tile 19V.", "8pm", briefing = "Finding the refrigerators holding biological samples took longer than expected. The scientists had collected many dangerous materials; if those diseases mixed with zombies, even experienced Survivors would be at risk. Penny was changing as she faced the possibility of finding her mother’s body.", objectives = listOf("Destroy the laboratories and any Zombies standing in them. Take the Refrigerators Objective card on tile 19V.", "Starting hour: 8pm."), specialRules = listOf("The Green door cannot be opened.", "Penny’s Leader gets the +1 free Combat Action Skill. This free Combat Action can only be performed with a weapon in the Leader’s Backpack.", "Each Pimpweapon Crate gives a random Pimpweapon; the Survivor may reorganize inventory for free."), materials = listOf("6 Survivor Starting Zone markers", "Locked door token", "6 Pimpweapon Crates", "8 Objective cards", "2 Notes", "Spawn Zone tokens"))
)
val fortMissionInfo: Map<String, FortMissionInfo> = fortMissionInfoBase + fortMissionDetails
